using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task ChatRespondsRelevantly()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Chat response should not be empty.");

        // Evaluate response quality using AI evaluators
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(chatClient);
        var evaluationResult = await EvaluateAsync(chatConfiguration, messages, response, evaluators);

        foreach (var metric in evaluationResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }

    [TestMethod]
    public async Task ChatHandlesFollowUp()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire in one sentence."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Chat response should not be empty.");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new GroundednessEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(chatClient);
        var evaluationResult = await EvaluateAsync(chatConfiguration, messages, response, evaluators);

        foreach (var metric in evaluationResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }

    private static async Task<IDictionary<string, MetricValue>> EvaluateAsync(
        ChatConfiguration chatConfiguration,
        IList<ChatMessage> messages,
        ChatResponse response,
        IEnumerable<IEvaluator> evaluators)
    {
        var turnContext = new TurnContext(messages, response.Messages);

        var results = new Dictionary<string, MetricValue>();
        foreach (var evaluator in evaluators)
        {
            var metrics = await evaluator.EvaluateAsync(turnContext, chatConfiguration);
            foreach (var metric in metrics)
            {
                results[metric.Identifier] = metric.Value;
            }
        }

        return results;
    }
}

